package com.wtm.ui;

import com.wtm.ingest.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.io.File;

/** Import + connector surface used by Data Collection without nested tabs. */
public final class DataCollectionConnectionsPanel extends JPanel {
 private final DataIngestionService service=DataIngestionService.get();private final GmailDataPathService gmail=GmailDataPathService.get();private JLabel gmailStatus;
 public DataCollectionConnectionsPanel(){super(new BorderLayout(10,10));setBackground(Theme.bg());setBorder(new EmptyBorder(12,4,4,4));JPanel stack=new JPanel();stack.setOpaque(false);stack.setLayout(new BoxLayout(stack,BoxLayout.Y_AXIS));stack.add(importCard());stack.add(Box.createVerticalStrut(10));stack.add(gmailCard());stack.add(Box.createVerticalStrut(10));stack.add(infoCard("Microsoft 365 / Graph","ENTERPRISE READY • REQUIRES IT AUTHORIZATION","Production target. The independent development build does not request company tenant credentials or Graph permissions."));JScrollPane sp=new JScrollPane(stack);sp.setBorder(null);sp.getVerticalScrollBar().setUnitIncrement(20);add(sp);NorthStarThemeCompliance.apply(this);}
 private JComponent importCard(){GlassSurfacePanel r=new GlassSurfacePanel(16);r.setLayout(new BorderLayout(10,10));r.setBorder(new EmptyBorder(16,16,16,16));JLabel h=new JLabel("FILE & DVIEW EXPORT INGESTION");h.setForeground(Theme.text());h.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));r.add(h,BorderLayout.NORTH);JPanel body=new JPanel();body.setOpaque(false);body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel d=new JLabel("<html>Import an individual CSV or a sectioned NorthStar bundle containing several DVIEW result sets. Every section still passes through normal schema validation and duplicate protection.</html>");d.setForeground(Theme.muted());body.add(d);body.add(Box.createVerticalStrut(10));JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));b.setOpaque(false);JButton csv=new JButton("Import CSV"),bundle=new JButton("Import NorthStar Bundle"),folder=new JButton("Open Incoming Folder"),scan=new JButton("Scan Folder Now");b.add(csv);b.add(bundle);b.add(folder);b.add(scan);body.add(b);body.add(Box.createVerticalStrut(10));JPanel opts=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));opts.setOpaque(false);JCheckBox watch=new JCheckBox("Watch incoming folder",service.watchEnabled()),auto=new JCheckBox("Validated auto-import",service.autoImport());watch.setOpaque(false);auto.setOpaque(false);opts.add(watch);opts.add(auto);body.add(opts);JLabel format=new JLabel("Bundle markers: __NORTHSTAR_DATASET__,<dataset name>  ...CSV rows...  __END_DATASET__");format.setForeground(Theme.muted());body.add(Box.createVerticalStrut(8));body.add(format);r.add(body);csv.addActionListener(e->importCsv(r));bundle.addActionListener(e->importBundle(r));folder.addActionListener(e->{try{Desktop.getDesktop().open(service.incoming().toFile());}catch(Exception ex){msg(r,ex.getMessage());}});scan.addActionListener(e->{service.scanIncoming();msg(r,"Incoming folder scan complete.");});watch.addActionListener(e->service.setWatchEnabled(watch.isSelected()));auto.addActionListener(e->service.setAutoImport(auto.isSelected()));return r;}
 private JComponent gmailCard(){GlassSurfacePanel r=new GlassSurfacePanel(16);r.setLayout(new BorderLayout(10,10));r.setBorder(new EmptyBorder(16,16,16,16));JPanel head=new JPanel(new BorderLayout());head.setOpaque(false);JLabel title=new JLabel("GMAIL DATAPATH • DEVELOPMENT CONNECTOR");title.setForeground(Theme.text());title.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));gmailStatus=new JLabel();gmailStatus.setHorizontalAlignment(SwingConstants.RIGHT);head.add(title);head.add(gmailStatus,BorderLayout.EAST);r.add(head,BorderLayout.NORTH);JPanel body=new JPanel();body.setOpaque(false);body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel desc=new JLabel("<html>Read-only Gmail ingestion. Attachments are routed through the same Data Collection validators. OAuth credentials and refresh tokens remain in local application data, not the JAR.</html>");desc.setForeground(Theme.muted());body.add(desc);body.add(Box.createVerticalStrut(10));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));actions.setOpaque(false);JButton client=new JButton("Choose OAuth JSON"),connect=new JButton("Connect Gmail"),check=new JButton("Check Now");actions.add(client);actions.add(connect);actions.add(check);body.add(actions);body.add(Box.createVerticalStrut(8));JPanel opts=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));opts.setOpaque(false);JCheckBox automatic=new JCheckBox("Automatic checks",gmail.autoCheck());automatic.setOpaque(false);JSpinner interval=new JSpinner(new SpinnerNumberModel(gmail.intervalMinutes(),5,1440,5));JTextField senders=new JTextField(gmail.approvedSenders(),28);opts.add(automatic);opts.add(new JLabel("Every"));opts.add(interval);opts.add(new JLabel("min"));opts.add(new JLabel("Approved senders"));opts.add(senders);body.add(opts);r.add(body);Runnable status=()->{var s=gmail.status();gmailStatus.setText(s.connected()?"● CONNECTED • "+s.mailbox():s.configured()?"● READY TO AUTHORIZE":"○ NOT CONFIGURED");gmailStatus.setForeground(s.connected()?new Color(40,205,150):Theme.muted());};status.run();client.addActionListener(e->{JFileChooser fc=new JFileChooser();if(fc.showOpenDialog(r)==JFileChooser.APPROVE_OPTION)try{gmail.installClientJson(fc.getSelectedFile().toPath());status.run();msg(r,"OAuth client configuration installed locally.");}catch(Exception ex){msg(r,ex.getMessage());}});connect.addActionListener(e->{connect.setEnabled(false);new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return gmail.connectInteractive();}protected void done(){connect.setEnabled(true);try{msg(r,"Connected to "+get()+" with read-only Gmail access.");}catch(Exception ex){msg(r,root(ex));}status.run();}}.execute();});check.addActionListener(e->{check.setEnabled(false);gmail.setApprovedSenders(senders.getText());gmail.setIntervalMinutes((Integer)interval.getValue());gmail.setAutoCheck(automatic.isSelected());new SwingWorker<GmailDataPathService.SyncResult,Void>(){protected GmailDataPathService.SyncResult doInBackground()throws Exception{return gmail.syncNow();}protected void done(){check.setEnabled(true);try{var x=get();msg(r,"Sync complete.\nMessages scanned: "+x.messages()+"\nNew CSV attachments: "+x.csvAttachments()+"\nImported: "+x.imported()+"\nDuplicate / review: "+x.duplicateOrReview());}catch(Exception ex){msg(r,root(ex));}status.run();}}.execute();});automatic.addActionListener(e->gmail.setAutoCheck(automatic.isSelected()));interval.addChangeListener(e->gmail.setIntervalMinutes((Integer)interval.getValue()));senders.addActionListener(e->gmail.setApprovedSenders(senders.getText()));return r;}
 private JComponent infoCard(String title,String state,String text){GlassSurfacePanel r=new GlassSurfacePanel(16);r.setLayout(new BorderLayout(8,5));r.setBorder(new EmptyBorder(14,16,14,16));JLabel h=new JLabel(title+"   •   "+state);h.setForeground(Theme.text());h.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));JLabel d=new JLabel("<html>"+text+"</html>");d.setForeground(Theme.muted());r.add(h,BorderLayout.NORTH);r.add(d);return r;}
 private void importCsv(Component owner){JFileChooser fc=new JFileChooser();fc.setMultiSelectionEnabled(true);if(fc.showOpenDialog(owner)==JFileChooser.APPROVE_OPTION)for(File f:fc.getSelectedFiles())try{IngestionRecord x=service.importFile(f.toPath(),"Data Collection");msg(owner,x.status()+" • "+x.detectedType()+" • "+x.records()+" rows");}catch(Exception ex){msg(owner,ex.getMessage());}}
 private void importBundle(Component owner){JFileChooser fc=new JFileChooser();fc.setDialogTitle("Select sectioned NorthStar DVIEW bundle");if(fc.showOpenDialog(owner)==JFileChooser.APPROVE_OPTION)try{var x=SectionedImportService.importBundle(fc.getSelectedFile().toPath(),"NorthStar Bundle");msg(owner,"Bundle processed.\nSections: "+x.sections()+"\nImported: "+x.imported()+"\nReview/duplicate: "+x.review()+"\n\n"+String.join("\n",x.details()));}catch(Exception ex){msg(owner,ex.getMessage());}}
 private static String root(Throwable t){Throwable x=t;while(x.getCause()!=null)x=x.getCause();return x.getMessage()==null?x.toString():x.getMessage();}private static void msg(Component c,String s){JOptionPane.showMessageDialog(c,s==null?"Unknown error":s,"NorthStar Data Collection",JOptionPane.INFORMATION_MESSAGE);}
}
